llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C59"],
      "claim": "KNI-272, the closest peptidomimetic protease inhibitor analogue, showed 36.4% absolute oral bioavailability post-prandially in patients, directly supporting F ≥20% under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "KNI-272 capsule bioavailability ranged from approximately 22% to 55% across adult studies, confirming consistent F above the 20% threshold for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Indinavir, another HIV protease inhibitor with a similar hydroxyethylamine core, had systemic bioavailability of 60% in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Remikiren, a more peptidic renin inhibitor, had extremely low F (0.3%), providing a cautionary low-bioavailability example, but its lower transferability and different terminal pharmacophores limit weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a nelfinavir-like HIV protease inhibitor with a tert-butylamide decahydroisoquinoline and hydroxyethylamine core. The closest analogue KNI-272 shows adult absolute F of 29–55%, including 36.4% post-prandially, and other HIV protease inhibitors such as indinavir support F ≥20%. Low-F examples like remikiren are structurally more distant and less transferable. Under fed conditions, lipophilic protease inhibitors generally show improved absorption, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the query molecule itself; all evidence comes from analogues with low Morgan similarity.",
    "Fed-state data are available mainly for KNI-272; most other analogues were studied under fasting conditions.",
    "The F ≥20% threshold is borderline for some protease inhibitors, and variability across formulations and patient populations is substantial."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

